const H = 2.7;
// Модель высот: y=0 — чистовой пол; все высоты (мебель, проёмы, потолок H, рост человечка, H-адреса) — от него.
// Слои пола лежат чуть выше нуля, чтобы не мерцать друг с другом: черновой 0.001, клетки 0.003, отделка 0.006, адресная сетка 0.009
const FLOOR = 0.006;
const VIEWS=["data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,", "data:image/jpeg;base64,"];
const NAMES = {1:'Комната 1',2:'Комната 2',3:'Комната 3',4:'Кухня-гостиная',5:'Коридор',6:'Пом. 6',7:'Пом. 7',8:'Пом. 8',9:'С/у',10:'Балкон'};

function isDark(){
  const t=document.documentElement.getAttribute('data-theme');
  if(t==='dark')return true; if(t==='light')return false;
  return matchMedia('(prefers-color-scheme: dark)').matches;
}

const canvas=document.getElementById('c');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true});
renderer.setPixelRatio(Math.min(devicePixelRatio,2));
const scene=new THREE.Scene();

// bounds
let minX=1e9,maxX=-1e9,minZ=1e9,maxZ=-1e9;
PLAN.outer.forEach(p=>{minX=Math.min(minX,p[0]);maxX=Math.max(maxX,p[0]);minZ=Math.min(minZ,p[1]);maxZ=Math.max(maxZ,p[1]);});
const cx=(minX+maxX)/2, cz=(minZ+maxZ)/2, span=Math.max(maxX-minX,maxZ-minZ);
// начало координат адресации (клетки A1, D7+26) зафиксировано в плане: изменение контура не меняет смысл старых адресов
const ORG=(PLAN.meta&&PLAN.meta.origin)||[minX,minZ];

const persp=new THREE.PerspectiveCamera(45,1,0.5,300);
// режим плана («Сверху»): ортографическая камера строго вниз, север вверху — одинаковые размеры на любой высоте
const ortho=new THREE.OrthographicCamera(-1,1,1,-1,0.1,300);
let camera=persp; // текущая камера: persp в прогулке и 3D, ortho в плане
const PANEL_W=320, MAP_W=200; // панель слева и мини-карта справа с полями — план вписывается между ними
const TAN22=Math.tan(45/2*Math.PI/180); // при равном r видимая высота в ортографии равна перспективной у цели

// Встроенное орбитальное управление (без внешних зависимостей)
const controls={
  target:new THREE.Vector3(cx,0,cz),
  r:20, theta:0.8, phi:1.0,
  minPhi:0.012, maxPhi:Math.PI/2-0.02, minR:2, maxR:120,
  setPose(px,py,pz,tx,ty,tz){
    this.plan=false;
    if(persp.fov!==45){persp.fov=45;persp.updateProjectionMatrix();}
    const zs=document.getElementById('zoom'); if(zs){zs.value=100;document.getElementById('zov').textContent='100%';}
    this.target.set(tx,ty,tz);
    const dx=px-tx, dy=py-ty, dz=pz-tz;
    this.r=Math.max(this.minR,Math.sqrt(dx*dx+dy*dy+dz*dz));
    this.r0=this.r;
    this.phi=Math.acos(Math.min(1,Math.max(-1,dy/this.r)));
    this.theta=Math.atan2(dx,dz);
    this.apply();
  },
  fpv:false, plan:false, pos:new THREE.Vector3(),
  dir(){
    const sp=Math.sin(this.phi);
    return new THREE.Vector3(sp*Math.sin(this.theta),Math.cos(this.phi),sp*Math.cos(this.theta));
  },
  setPlan(){ // вид сверху: план вписывается в область правее панели, север вверху
    this.plan=true; this.fpv=false;
    const zs=document.getElementById('zoom'); if(zs){zs.value=100;document.getElementById('zov').textContent='100%';}
    const aw=Math.max(200,innerWidth-PANEL_W-MAP_W), ah=innerHeight-32;
    const hh=Math.max((maxZ-minZ)/2*1.08, (maxX-minX)/2*1.08*innerHeight/aw); // половина видимой высоты, м
    this.r=hh/TAN22; this.r0=this.r; this.theta=0; this.phi=this.minPhi;
    this.target.set(cx-((PANEL_W-MAP_W)/2)*(2*hh/innerHeight),0,cz); // центр квартиры — в центре свободной области
    this.apply();
  },
  lookDown(){ this.theta=0; this.phi=this.minPhi; this.apply(); }, // ровный план для разметки и расстановки
  setFPV(x,z,theta){
    this.fpv=true; this.plan=false;
    persp.fov=60; persp.updateProjectionMatrix();
    const zs=document.getElementById('zoom'); if(zs){zs.value=100;document.getElementById('zov').textContent='100%';}
    this.pos.set(x,1.57,z);
    this.theta=theta; this.phi=Math.PI/2+0.03;
    this.apply();
  },
  apply(){
    camera=this.plan?ortho:persp;
    if(typeof avatar!=='undefined'){ avatar.visible=this.fpv; }
    if(typeof backdropGroup!=='undefined'){ backdropGroup.visible=this.fpv; }
    if(typeof ceilGroup!=='undefined') ceilGroup.visible=!this.plan&&document.getElementById('ceil').checked; // hidden in plan; set before the fpv return so walk mode restores it
    if(this.fpv){
      this.phi=Math.min(Math.PI-0.25,Math.max(0.25,this.phi));
      const d=this.dir();
      const head=this.pos.clone(); head.y=1.57;
      if(typeof avatar!=='undefined'){
        avatar.position.set(this.pos.x,0,this.pos.z);
        avatar.rotation.y=this.theta;
      }
      // камера за левым плечом, на уровне головы; не дальше ближайшей стены
      const dh=d.clone(); dh.y=0; dh.normalize();
      const left=new THREE.Vector3(dh.z,0,-dh.x);
      let back=2.4;
      if(typeof wallGroup!=='undefined'){
        tpRay.set(head, dh.clone().negate());
        const hits=tpRay.intersectObjects(wallGroup.children.concat(wallGroupR.visible?wallGroupR.children:[]).concat(typeof physGroup!=='undefined'?physGroup.children.filter(o=>{const bb=new THREE.Box3().setFromObject(o);return bb.min.y<1.6&&bb.max.y>1.4;}):[]),false)
          .filter(h=>h.object.isMesh); // камера не заходит в стену и в мебель на высоте головы
        if(hits.length) back=Math.max(0.9,Math.min(back,hits[0].distance-0.12));
      if(typeof avatarMat!=='undefined') avatarMat.opacity = back<1.3 ? 0.45 : 0.92;
      }
      const off=0.34*back/2.4; // сдвиг к плечу пропорционален дистанции
      const camPos=head.clone().addScaledVector(dh,-back).addScaledVector(left,off);
      camPos.y=1.60;
      camera.position.copy(camPos);
      camera.lookAt(head.clone().addScaledVector(d,Math.max(back,1.5)));
      return;
    }
    this.phi=Math.min(this.maxPhi,Math.max(this.minPhi,this.phi));
    this.r=Math.min(this.maxR,Math.max(this.minR,this.r));
    if(this.plan){
      const hh=this.r*TAN22, a=innerWidth/innerHeight;
      ortho.top=hh; ortho.bottom=-hh; ortho.left=-hh*a; ortho.right=hh*a; ortho.updateProjectionMatrix();
    }
    const sp=Math.sin(this.phi);
    camera.position.set(
      this.target.x+this.r*sp*Math.sin(this.theta),
      this.target.y+this.r*Math.cos(this.phi),
      this.target.z+this.r*sp*Math.cos(this.theta));
    camera.lookAt(this.target);
  },
  update(){}
};
(function(){
  const ptrs=new Map(); let mode=null, px=0, py=0, pinch=0, space=false, pmx=0, pmy=0;
  const panbtn=document.getElementById('panbtn'); // сенсорный аналог зажатого пробела
  addEventListener('keydown',e=>{
    if(e.code==='Space'){ space=true; if(e.target===document.body)e.preventDefault(); }
    if(controls.fpv && walkKeys.hasOwnProperty(e.code)){ walkKeys[e.code]=true; e.preventDefault(); }
  });
  addEventListener('keyup',e=>{
    if(e.code==='Space') space=false;
    if(walkKeys.hasOwnProperty(e.code)) walkKeys[e.code]=false;
  });
  canvas.style.touchAction='none';
  canvas.addEventListener('contextmenu',e=>e.preventDefault());
  canvas.addEventListener('pointerdown',e=>{
    try{canvas.setPointerCapture(e.pointerId);}catch(_){} // синтетические события без активного указателя
    ptrs.set(e.pointerId,e);
    if(ptrs.size===2){
      const [a,b]=[...ptrs.values()];
      pinch=Math.hypot(a.clientX-b.clientX,a.clientY-b.clientY);
      pmx=(a.clientX+b.clientX)/2; pmy=(a.clientY+b.clientY)/2;
      mode='pinch';
    } else { const tools=(window.MK&&MK.on)||(window.LAY&&LAY.on); mode=(e.button===2||e.shiftKey||space||panbtn.classList.contains('on')||(controls.plan&&tools))?'pan':'rot'; /* в плане ЛКМ вращает, при разметке/расстановке — сдвигает */ px=e.clientX; py=e.clientY; }
  });
  canvas.addEventListener('pointermove',e=>{
    if(!ptrs.has(e.pointerId))return;
    ptrs.set(e.pointerId,e);
    if(mode==='pinch'&&ptrs.size===2){
      const [a,b]=[...ptrs.values()];
      const d=Math.hypot(a.clientX-b.clientX,a.clientY-b.clientY);
      if(pinch>0){
        if(controls.fpv){ const w=controls.dir(); w.y=0; w.normalize(); moveFPV(w.multiplyScalar((d-pinch)*0.01)); }
        else controls.r*=pinch/d;
      }
      // двумя пальцами тянуть = сдвиг сцены (вид сверху)
      const mx=(a.clientX+b.clientX)/2, my=(a.clientY+b.clientY)/2;
      if(!controls.fpv){
        const s=controls.plan?2*ortho.top/innerHeight:controls.r*0.0013;
        const right=new THREE.Vector3().setFromMatrixColumn(camera.matrix,0);
        const up=new THREE.Vector3().setFromMatrixColumn(camera.matrix,1);
        controls.target.addScaledVector(right,-(mx-pmx)*s).addScaledVector(up,(my-pmy)*s);
      }
      pmx=mx; pmy=my;
      pinch=d; controls.apply(); return;
    }
    const dx=e.clientX-px, dy=e.clientY-py; px=e.clientX; py=e.clientY;
    if(mode==='rot'){
      if(controls.fpv){ controls.theta-=dx*0.0035; controls.phi-=dy*0.0035; }
      else { controls.theta-=dx*0.005; controls.phi-=dy*0.005; }
    }
    else if(mode==='pan'){
      if(controls.fpv){
        const d=controls.dir(); d.y=0; d.normalize();
        const right=new THREE.Vector3(d.z,0,-d.x);
        moveFPV(right.multiplyScalar(dx*0.004).addScaledVector(d,dy*0.004));
      } else {
        const s=controls.plan?2*ortho.top/innerHeight:controls.r*0.0013;
        const right=new THREE.Vector3().setFromMatrixColumn(camera.matrix,0);
        const up=new THREE.Vector3().setFromMatrixColumn(camera.matrix,1);
        controls.target.addScaledVector(right,-dx*s).addScaledVector(up,dy*s);
      }
    }
    controls.apply();
  });
  const end=e=>{ ptrs.delete(e.pointerId); if(ptrs.size<2)pinch=0; if(!ptrs.size)mode=null; };
  canvas.addEventListener('pointerup',end);
  canvas.addEventListener('pointercancel',end);
  canvas.addEventListener('wheel',e=>{
    e.preventDefault();
    if(controls.fpv){
      const d=controls.dir(); d.y=0; d.normalize();
      moveFPV(d.multiplyScalar(-e.deltaY*0.0022));
    } else {
      controls.r*=Math.exp(e.deltaY*0.0012);
    }
    controls.apply();
  },{passive:false});
})();

function fitDist(mult){
  const fov=45*Math.PI/180;
  const dv=((maxZ-minZ)/2)/Math.tan(fov/2);
  const dh=((maxX-minX)/2)/(Math.tan(fov/2)*Math.max(persp.aspect,0.5));
  return Math.max(dv,dh)*(mult||1.12);
}
function setView(kind){
  if(typeof resizeReady!=='undefined')resize();
  controls.fpv=false;
  if(kind==='top'){controls.setPlan();}
  else if(kind==='eye'){controls.setPose(cx+span*0.62,1.7,cz+span*0.72,cx,1.3,cz);}
  else if(kind==='door'){controls.setFPV(7.35,8.6,Math.PI);}
  else if(kind==='room4'){controls.setFPV(11.0,3.4,-0.75);}
  else{const d=fitDist(0.78);controls.setPose(cx+d*0.72,d*0.82,cz+d*0.77,cx,0,cz);}
}

// lights
scene.add(new THREE.HemisphereLight(0xffffff,0xa8a49c,1.0));
const sun=new THREE.DirectionalLight(0xffffff,0.55);
sun.position.set(-6,14,-8);scene.add(sun);

function toShape(poly){
  const s=new THREE.Shape();
  poly.forEach((p,i)=>{ i?s.lineTo(p[0],-p[1]):s.moveTo(p[0],-p[1]); });
  return s;
}

// стены: слои с вырезами дверей и окон
const wallMat=new THREE.MeshBasicMaterial({color:0xfaf8f5,transparent:false,opacity:1,side:THREE.FrontSide});
const wallEdgeMat=new THREE.LineBasicMaterial({color:0x63605a,transparent:true,opacity:1});
function buildWalls(slabs){
  const grp=new THREE.Group();
  slabs.forEach(sl=>{
    sl.polys.forEach(pg=>{
      const sh=toShape(pg.s);
      sh.holes=pg.h.map(hp=>{
        const path=new THREE.Path();
        hp.forEach((p,i)=> i?path.lineTo(p[0],-p[1]):path.moveTo(p[0],-p[1]));
        return path;
      });
      const g=new THREE.ExtrudeGeometry(sh,{depth:sl.y1-sl.y0,bevelEnabled:false});
      g.rotateX(-Math.PI/2); g.translate(0,sl.y0,0);
      grp.add(new THREE.Mesh(g,wallMat));
      grp.add(new THREE.LineSegments(new THREE.EdgesGeometry(g,30),wallEdgeMat));
    });
  });
  return grp;
}
const wallGroup=buildWalls(PLAN.slabs);
scene.add(wallGroup);
// плита этажа
const lotMat=new THREE.MeshBasicMaterial({color:0xb8b6b2});
const lot=new THREE.Mesh(new THREE.BoxGeometry((maxX-minX)+14,0.1,(maxZ-minZ)+14),lotMat);
lot.position.set(cx,-0.062,cz);
scene.add(lot);
// общий коридор до входа: сплошные белые стены
function hallWall(sx,sz,px,pz){
  const g=new THREE.BoxGeometry(sx,H,sz);
  const m=new THREE.Mesh(g,wallMat); m.position.set(px,H/2,pz);
  wallGroup.add(m);
  const e=new THREE.LineSegments(new THREE.EdgesGeometry(g,30),wallEdgeMat);
  e.position.copy(m.position);
  wallGroup.add(e);
}
hallWall(0.15,5.85, 6.55,10.68);  // западная стена коридора (вдоль квартиры, на юг)
hallWall(0.12,1.70, 8.09,10.73);  // закрывает нишу квартиры со стороны коридора

const wallGroupR=buildWalls(PLAN.slabsR);
scene.add(wallGroupR);

// floors per room
const floorMats=[];
PLAN.rooms.forEach(r=>{
  const g=new THREE.ShapeGeometry(toShape(r.poly));
  g.rotateX(-Math.PI/2); g.translate(0,0.001,0); // черновой пол комнаты — под клетками (0.003) и отделкой (FLOOR)
  const m=new THREE.MeshBasicMaterial({color:0x9b9994,side:THREE.DoubleSide});
  floorMats.push(m);
  scene.add(new THREE.Mesh(g,m));
});
// base slab
const baseGeo=new THREE.ExtrudeGeometry(toShape(PLAN.outer),{depth:0.12,bevelEnabled:false});
baseGeo.rotateX(-Math.PI/2); baseGeo.translate(0,-0.12,0);
const baseMat=new THREE.MeshLambertMaterial({color:0xcfcabf});
scene.add(new THREE.Mesh(baseGeo,baseMat));

// cubes
const cubeGroup=new THREE.Group();
const edgeMat=new THREE.LineBasicMaterial({color:0x2c5aa0,transparent:true,opacity:.6});
PLAN.rooms.forEach(r=>{
  r.cells.forEach(c=>{
    const [x,z,w,d]=c;
    for(let y0=0;y0<H-0.05;y0+=1){
      const hh=Math.min(1,H-y0);
      const g=new THREE.BoxGeometry(Math.max(w-0.01,0.05),hh,Math.max(d-0.01,0.05));
      const e=new THREE.LineSegments(new THREE.EdgesGeometry(g),edgeMat);
      e.position.set(x+w/2,y0+hh/2,z+d/2);
      cubeGroup.add(e);
    }
  });
});
scene.add(cubeGroup);
cubeGroup.visible=false;

// 2D-разметка пола: квадраты 1×1 м
const gridGroup=new THREE.Group();
const cellMatA=new THREE.MeshBasicMaterial({color:0xa9a7a2,side:THREE.DoubleSide});
const cellLine=new THREE.LineBasicMaterial({color:0x555350});
PLAN.rooms.forEach(r=>{
  r.cells.forEach(c=>{
    const [x,z,w,d,k]=c;
    if(k===0){
      const pg=new THREE.PlaneGeometry(w,d);
      pg.rotateX(-Math.PI/2);
      const pm=new THREE.Mesh(pg,cellMatA);
      pm.position.set(x+w/2,0.003,z+d/2);
      gridGroup.add(pm);
    }
    const eg=new THREE.BufferGeometry().setFromPoints([
      new THREE.Vector3(x,0.004,z), new THREE.Vector3(x+w,0.004,z),
      new THREE.Vector3(x+w,0.004,z+d), new THREE.Vector3(x,0.004,z+d),
      new THREE.Vector3(x,0.004,z)]);
    gridGroup.add(new THREE.Line(eg,cellLine));
  });
});
scene.add(gridGroup);

// интерактивные точки-аннотации
const labelGroup=new THREE.Group();
const dotTex=(()=>{
  const cv=document.createElement('canvas');cv.width=64;cv.height=64;
  const g=cv.getContext('2d');
  g.beginPath();g.arc(32,32,22,0,Math.PI*2);
  g.fillStyle='#2c5aa0';g.fill();
  g.lineWidth=6;g.strokeStyle='#ffffff';g.stroke();
  return new THREE.CanvasTexture(cv);
})();
const dots=[];
PLAN.rooms.forEach(r=>{
  const sp=new THREE.Sprite(new THREE.SpriteMaterial({map:dotTex,depthTest:false,transparent:true}));
  sp.scale.set(0.34,0.34,1);
  sp.position.set(r.label[0],H+0.25,r.label[1]);
  sp.renderOrder=10;
  let xs=r.poly.map(p=>p[0]), zs=r.poly.map(p=>p[1]);
  sp.userData={id:r.id, area:r.area,
    w:(Math.max(...xs)-Math.min(...xs)).toFixed(2).replace('.',','),
    d:(Math.max(...zs)-Math.min(...zs)).toFixed(2).replace('.',',')};
  dots.push(sp); labelGroup.add(sp);
});
scene.add(labelGroup);
labelGroup.visible=false; // по умолчанию выключено, как и галочка #labels

// tooltip
const tip=document.createElement('div');
tip.id='tip'; tip.hidden=true; document.body.appendChild(tip);
let activeDot=null;
function showTip(dot){
  activeDot=dot;
  if(!dot){tip.hidden=true;return;}
  const u=dot.userData;
  tip.innerHTML='<b>Помещение '+u.id+'</b><br>'+String(u.area).replace('.',',')+' м² · '+u.w+' × '+u.d+' м';
  tip.hidden=false;
}
function placeTip(){
  if(!activeDot||tip.hidden)return;
  const v=activeDot.position.clone().project(camera);
  if(v.z>1){tip.hidden=true;return;}
  tip.style.left=((v.x+1)/2*innerWidth)+'px';
  tip.style.top=((1-(v.y+1)/2)*innerHeight-14)+'px';
}
const ray=new THREE.Raycaster();
let downX=0, downY=0;
canvas.addEventListener('pointerdown',e=>{downX=e.clientX;downY=e.clientY;});
canvas.addEventListener('pointerup',e=>{
  if(Math.hypot(e.clientX-downX,e.clientY-downY)>6)return;
  if(!labelGroup.visible){showTip(null);return;}
  const ndc=new THREE.Vector2(e.clientX/innerWidth*2-1,-(e.clientY/innerHeight*2-1));
  ray.setFromCamera(ndc,camera);
  const hits=ray.intersectObjects(dots);
  showTip(hits.length?(hits[0].object===activeDot?null:hits[0].object):null);
});

// theme
function applyTheme(){
  scene.background=new THREE.Color(0xffffff);
  baseMat.color.set(0xd8d4cb);
}
applyTheme();

// UI
