const wop=document.getElementById('wop'),wov=document.getElementById('wov');
const fade=(m,v)=>{ m.opacity=v; m.transparent=v<0.999; m.depthWrite=v>=0.5; m.needsUpdate=true; const s=window.VIZ&&VIZ.std.get(m); if(s) fade(s,v); }; // PBR twin follows the basic material
wop.addEventListener('input',()=>{
  const v=wop.value/100;
  fade(wallMat,v);
  wallGroup.visible=v>0.01;
  wallGroupR.visible=v>0.01&&document.getElementById('kwall').checked;
  wallEdgeMat.opacity=1;
  // настенная отделка следует за стенами: та же прозрачность, скрывается вместе с ними; пол не трогаем
  if(window.wallFinMats) window.wallFinMats.forEach(m=>fade(m,v));
  if(window.wallFin) window.wallFin.visible=v>0.01;
  wov.textContent=wop.value+'%';
});
const zoom=document.getElementById('zoom'),zov=document.getElementById('zov');
zoom.addEventListener('input',()=>{
  zov.textContent=zoom.value+'%';
  if(controls.fpv){
    persp.fov=Math.min(85,Math.max(25,60*Math.sqrt(100/zoom.value)));
    persp.updateProjectionMatrix();
  } else {
    controls.r=(controls.r0||controls.r)*100/zoom.value; controls.apply();
  }
});
document.getElementById('vTop').addEventListener('click',()=>setView('top'));
document.getElementById('vFP').addEventListener('click',()=>setView('door'));
const fpvhint=document.getElementById('fpvhint');
const walkpad=document.getElementById('walkpad');
const panbtn=document.getElementById('panbtn');
panbtn.addEventListener('click',()=>panbtn.classList.toggle('on'));
// размер сенсорных кнопок ~80 физических px экрана: страница без viewport meta рендерится в ~980
// виртуальных px и масштабируется под screen.width (iPhone 390 → крупно, iPad 810 → вдвое меньше)
function sizeTouchButtons(){
  const wk=Math.max(60,Math.min(220,Math.round(80*innerWidth/screen.width)));
  document.documentElement.style.setProperty('--wkjs',wk+'px');
}
sizeTouchButtons(); addEventListener('resize',sizeTouchButtons);
['vTop','vFP'].forEach(id=>document.getElementById(id).addEventListener('click',()=>{
  fpvhint.hidden=!controls.fpv; walkpad.hidden=!controls.fpv;
  panbtn.hidden=controls.fpv; panbtn.classList.remove('on');
  document.querySelector('.hint').textContent=controls.plan?'ЛКМ — вращать · колесо — масштаб · ПКМ или пробел — сдвиг':'ЛКМ — вращать · колесо — зум · ПКМ или пробел — сдвиг';
}));
// экранные кнопки прогулки ставят те же флаги, что и клавиатура
walkpad.querySelectorAll('button').forEach(b=>{
  const set=v=>e=>{e.preventDefault();walkKeys[b.dataset.key]=v;};
  b.addEventListener('pointerdown',set(true));
  b.addEventListener('pointerup',set(false));
  b.addEventListener('pointercancel',set(false));
  b.addEventListener('contextmenu',e=>e.preventDefault());
});

function resize(){
  const w=innerWidth,h=innerHeight;
  renderer.setSize(w,h,false);
  persp.aspect=w/h;persp.updateProjectionMatrix();
  if(controls.plan) controls.apply(); // ортографический фрустум пересчитывается от нового соотношения сторон
}
addEventListener('resize',resize);resize();
