// сетка 1 м на стенах (по границам кубов каждой комнаты)
var wallGridGroup=new THREE.Group();
(function(){
  const mat=new THREE.LineBasicMaterial({color:0x9c9a95,transparent:true,opacity:0.8});
  const pts=[];
  PLAN.rooms.forEach(r=>{
    const poly=r.poly;
    let area=0;
    for(let i=0;i<poly.length;i++){const j=(i+1)%poly.length;area+=poly[i][0]*poly[j][1]-poly[j][0]*poly[i][1];}
    const ccw=area>0;
    const xs=poly.map(p=>p[0]), zs=poly.map(p=>p[1]);
    const x0=Math.min(...xs), z0=Math.min(...zs);
    for(let i=0;i<poly.length;i++){
      const a=poly[i], b=poly[(i+1)%poly.length];
      const ex=b[0]-a[0], ez=b[1]-a[1];
      const len=Math.hypot(ex,ez); if(len<0.3) continue;
      // нормаль внутрь комнаты
      let nx=-ez/len, nz=ex/len;
      if(!ccw){nx=-nx;nz=-nz;}
      const off=0.02;
      const ax=a[0]+nx*off, az=a[1]+nz*off, bx=b[0]+nx*off, bz=b[1]+nz*off;
      // горизонтальные линии на высотах 1 и 2 м
      [1,2].forEach(y=>{
        pts.push(new THREE.Vector3(ax,y,az), new THREE.Vector3(bx,y,bz));
      });
      // вертикальные линии по границам метровых клеток
      const horiz=Math.abs(ex)>Math.abs(ez);
      const start=horiz?x0:z0;
      const a1=horiz?a[0]:a[1], b1=horiz?b[0]:b[1];
      const lo=Math.min(a1,b1), hi=Math.max(a1,b1);
      for(let k=Math.ceil((lo-start)/1);;k++){
        const v=start+k*1;
        if(v>hi-0.05) break;
        if(v<lo+0.05) continue;
        const t=(v-a1)/(b1-a1);
        const px=ax+(bx-ax)*t, pz=az+(bz-az)*t;
        pts.push(new THREE.Vector3(px,0,pz), new THREE.Vector3(px,H,pz));
      }
    }
  });
  const g=new THREE.BufferGeometry().setFromPoints(pts);
  wallGridGroup.add(new THREE.LineSegments(g,mat));
})();
scene.add(wallGridGroup);

// сетка-адресация: метровые клетки A1..O12 (буквы с запада, цифры с севера) + дециметровая сетка.
// Адрес квадратика: D7+26 = угол клетки D7, 2 дм на восток, 6 дм на юг; высота — H в дм от пола (H0–H27)
var addrGroup=new THREE.Group();
(function(){
  // пол: один канвас на всю квартиру — дециметровая сетка, метровые линии и подписи клеток
  const SC=64, W=maxX-ORG[0], D=maxZ-ORG[1];
  const c=document.createElement('canvas');
  c.width=Math.ceil(W*SC); c.height=Math.ceil(D*SC);
  const g=c.getContext('2d');
  g.beginPath();
  PLAN.outer.forEach((p,i)=>{const X=(p[0]-ORG[0])*SC,Y=(p[1]-ORG[1])*SC;i?g.lineTo(X,Y):g.moveTo(X,Y);});
  g.closePath(); g.clip();
  g.strokeStyle='rgba(120,118,112,0.30)'; g.lineWidth=1;
  g.beginPath();
  for(let x=0;x<=W;x+=0.1){g.moveTo(x*SC,0);g.lineTo(x*SC,c.height);}
  for(let z=0;z<=D;z+=0.1){g.moveTo(0,z*SC);g.lineTo(c.width,z*SC);}
  g.stroke();
  g.strokeStyle='rgba(80,78,72,0.75)'; g.lineWidth=2;
  g.beginPath();
  for(let x=0;x<=W;x+=1){g.moveTo(x*SC,0);g.lineTo(x*SC,c.height);}
  for(let z=0;z<=D;z+=1){g.moveTo(0,z*SC);g.lineTo(c.width,z*SC);}
  g.stroke();
  g.fillStyle='rgba(60,58,54,0.85)'; g.font='600 13px system-ui,sans-serif';
  g.textAlign='left'; g.textBaseline='top';
  for(let i=0;i<Math.ceil(W);i++)
    for(let j=0;j<Math.ceil(D);j++)
      g.fillText(String.fromCharCode(65+i)+(j+1), i*SC+4, j*SC+3);
  const tex=new THREE.CanvasTexture(c);
  const pg=new THREE.PlaneGeometry(W,D);
  pg.rotateX(-Math.PI/2);
  const m=new THREE.Mesh(pg,new THREE.MeshBasicMaterial({map:tex,transparent:true,depthWrite:false}));
  m.position.set(ORG[0]+W/2,FLOOR+0.003,ORG[1]+D/2); // чуть выше отделки пола
  addrGroup.add(m);

  // стены: дециметровые линии тем же обходом, что и метровая сетка, но от глобального нуля квартиры
  const mat=new THREE.LineBasicMaterial({color:0xa8a6a0,transparent:true,opacity:0.4});
  const pts=[];
  PLAN.rooms.forEach(r=>{
    const poly=r.poly;
    let area=0;
    for(let i=0;i<poly.length;i++){const j=(i+1)%poly.length;area+=poly[i][0]*poly[j][1]-poly[j][0]*poly[i][1];}
    const ccw=area>0;
    for(let i=0;i<poly.length;i++){
      const a=poly[i], b=poly[(i+1)%poly.length];
      const ex=b[0]-a[0], ez=b[1]-a[1];
      const len=Math.hypot(ex,ez); if(len<0.3) continue;
      let nx=-ez/len, nz=ex/len;
      if(!ccw){nx=-nx;nz=-nz;}
      const off=0.02;
      const ax=a[0]+nx*off, az=a[1]+nz*off, bx=b[0]+nx*off, bz=b[1]+nz*off;
      // горизонтали каждые 10 см (метровые уже есть в wallGridGroup)
      for(let y=0.1;y<H-0.01;y+=0.1){
        if(Math.abs(y-Math.round(y))<0.01) continue;
        pts.push(new THREE.Vector3(ax,y,az), new THREE.Vector3(bx,y,bz));
      }
      const horiz=Math.abs(ex)>Math.abs(ez);
      const start=horiz?ORG[0]:ORG[1];
      const a1=horiz?a[0]:a[1], b1=horiz?b[0]:b[1];
      const lo=Math.min(a1,b1), hi=Math.max(a1,b1);
      for(let k=Math.ceil((lo-start)/0.1);;k++){
        const v=start+k*0.1;
        if(v>hi-0.03) break;
        if(v<lo+0.03) continue;
        const t=(v-a1)/(b1-a1);
        const px=ax+(bx-ax)*t, pz=az+(bz-az)*t;
        pts.push(new THREE.Vector3(px,0,pz), new THREE.Vector3(px,H,pz));
      }
    }
  });
  const lg=new THREE.BufferGeometry().setFromPoints(pts);
  addrGroup.add(new THREE.LineSegments(lg,mat));
})();
scene.add(addrGroup);
wallGridGroup.visible=addrGroup.visible=document.getElementById('wgrid').checked; // по умолчанию выключена

// виртуальный человек (рост 1,8 м)
var walkKeys={ArrowUp:false,ArrowDown:false,ArrowLeft:false,ArrowRight:false,
  KeyW:false,KeyS:false,KeyA:false,KeyD:false};
var lastT=0;
function walkStep(t){
  const dt=Math.min((t-lastT)/1000,0.06); lastT=t;
  if(!controls.fpv) return;
  const fwd=(walkKeys.ArrowUp||walkKeys.KeyW?1:0)-(walkKeys.ArrowDown||walkKeys.KeyS?1:0);
  const strafe=(walkKeys.KeyD?1:0)-(walkKeys.KeyA?1:0);
  const turn=(walkKeys.ArrowLeft?1:0)-(walkKeys.ArrowRight?1:0);
  if(!fwd&&!strafe&&!turn) return;
  if(turn) controls.theta+=turn*1.8*dt;
  if(fwd||strafe){
    const d=controls.dir(); d.y=0; d.normalize();
    const right=new THREE.Vector3(-d.z,0,d.x);
    moveFPV(d.multiplyScalar(fwd*2.2*dt).addScaledVector(right,strafe*2.2*dt));
  }
  controls.apply();
}
var tpRay=new THREE.Raycaster();
var colRay=new THREE.Raycaster();
function moveFPV(delta){ // горизонтальное перемещение с проверкой стен
  const len=delta.length(); if(len<1e-6) return;
  if(typeof wallGroup!=='undefined'){
    const dirN=delta.clone().normalize();
    const objs=wallGroup.children.concat(wallGroupR.visible?wallGroupR.children:[]).concat(glassGroup.children).concat(typeof physGroup!=='undefined'?physGroup.children:[]).filter(o=>o.isMesh); // стены, окна и мебель (физика не зависит от видимости слоёв)
    let allowed=len;
    for(const h of [0.25,0.5,1.4]){ // колено, пояс, грудь: низкая мебель (сиденье 0.42) тоже препятствие
      colRay.set(new THREE.Vector3(controls.pos.x,h,controls.pos.z),dirN);
      colRay.far=len+0.30;
      const hits=colRay.intersectObjects(objs,false);
      if(hits.length) allowed=Math.min(allowed,hits[0].distance-0.30);
    }
    if(allowed<=0) return;
    controls.pos.addScaledVector(dirN,Math.min(allowed,len));
    return;
  }
  controls.pos.add(delta);
}
