// СЛОЙ 1: отделка (текстуры пола, стен, плитка санузлов, дверные коробки)
var finishGroup=new THREE.Group();
(function(){
  function canvasTex(drawFn){
    const c=document.createElement('canvas'); c.width=c.height=256;
    drawFn(c.getContext('2d'));
    const t=new THREE.CanvasTexture(c);
    t.wrapS=t.wrapT=THREE.RepeatWrapping;
    return t;
  }
  // серый ламинат: канвас = 1.9 x 1.9 м, длинные доски
  const lamTex=canvasTex(g=>{
    const tones=['#8d8a84','#84817b','#918e88','#7d7a74','#88857f','#827f79'];
    const rowH=26; // ~0.19 м
    for(let r=0;r<10;r++){
      const y=r*rowH;
      g.fillStyle=tones[(r*7)%tones.length];
      g.fillRect(0,y,256,rowH);
      // редкий поперечный стык, смещённый по рядам
      const jx=((r*97)%256);
      g.strokeStyle='rgba(45,42,38,0.30)';
      g.beginPath(); g.moveTo(jx+0.5,y); g.lineTo(jx+0.5,y+rowH); g.stroke();
      // разделитель рядов
      g.strokeStyle='rgba(45,42,38,0.32)';
      g.beginPath(); g.moveTo(0,y+0.5); g.lineTo(256,y+0.5); g.stroke();
      // лёгкая текстура волокон
      for(let i=0;i<4;i++){
        g.strokeStyle='rgba(55,50,46,'+(0.04+0.04*Math.random())+')';
        const gy=y+3+Math.random()*(rowH-6);
        g.beginPath(); g.moveTo(0,gy); g.bezierCurveTo(64,gy+2,192,gy-2,256,gy+1); g.stroke();
      }
    }
  });
  lamTex.repeat.set(1/1.9,1/1.9);
  function marble(base, grout, vein){
    return canvasTex(g=>{
      g.fillStyle=grout; g.fillRect(0,0,256,256);
      g.fillStyle=base; g.fillRect(2,2,252,252);
      for(let i=0;i<7;i++){
        g.strokeStyle=vein; g.lineWidth=0.8+Math.random()*1.5;
        g.beginPath();
        let x=Math.random()*256, y=0;
        g.moveTo(x,y);
        for(let k=0;k<4;k++){ x+=(Math.random()-0.5)*90; y+=64; g.lineTo(x,y); }
        g.stroke();
      }
    });
  }
  const whiteM=marble('#f1f0ec','#d5d4d0','rgba(140,142,148,0.28)');
  const greyM =marble('#9b9b9e','#7e7e81','rgba(230,230,235,0.30)');
  whiteM.repeat.set(1/0.6,1/0.6); greyM.repeat.set(1/0.6,1/0.6);
  // настенная отделка — отдельная подгруппа и отдельные материалы: ползунок «Стены» гасит её вместе со стенами, пол остаётся
  const wallFin=new THREE.Group(); finishGroup.add(wallFin); window.wallFin=wallFin;
  const lamMat=new THREE.MeshBasicMaterial({map:lamTex});
  const whiteMat=new THREE.MeshBasicMaterial({map:whiteM});
  const whiteWall=new THREE.MeshBasicMaterial({map:whiteM}); // та же плитка, но на стенах
  const greyMat=new THREE.MeshBasicMaterial({map:greyM});

  // белые обои под покраску: почти белые, мелкое зерно
  const wpTex=canvasTex(g=>{
    g.fillStyle='#fbfaf6'; g.fillRect(0,0,256,256);
    for(let i=0;i<1500;i++){
      g.fillStyle=Math.random()<0.55?'rgba(180,177,170,0.4)':'rgba(255,255,255,0.6)';
      const s=1+Math.random()*1.4;
      g.fillRect(Math.random()*256,Math.random()*256,s,s);
    }
  });
  wpTex.repeat.set(1/1.2,1/1.2);
  const wpMat=new THREE.MeshBasicMaterial({map:wpTex});

  function scaleUV(g,sx,sy){const uv=g.attributes.uv;for(let i=0;i<uv.count;i++)uv.setXY(i,uv.getX(i)*sx,uv.getY(i)*sy);}

  // полы: ламинат везде, кроме санузлов 8 и 9 (там белый мрамор)
  PLAN.rooms.forEach(r=>{
    const g=new THREE.ShapeGeometry(toShape(r.poly));
    g.rotateX(-Math.PI/2); g.translate(0,FLOOR,0);
    finishGroup.add(new THREE.Mesh(g,(r.id===7||r.id===8||r.id===9)?whiteMat:lamMat));
  });

  // пол общего коридора: белый мрамор
  {
    const g=new THREE.PlaneGeometry(1.48,5.80);
    scaleUV(g,1.48,5.80);
    g.rotateX(-Math.PI/2); 
    const m=new THREE.Mesh(g,whiteMat);
    m.position.set(7.31,FLOOR,10.66);
    finishGroup.add(m);
  }
  // плитка на стенах санузлов; стена напротив входа (западная) — серый мрамор
  const BATHS=PLAN.baths; // контуры санузлов и их дверей — в плане, двигаются вместе со стенами (remap)
  function panel(mat,w,h,cx,cy,cz,rotY){
    const g=new THREE.PlaneGeometry(w,h); scaleUV(g,w,h);
    g.rotateY(rotY);
    const m=new THREE.Mesh(g,mat);
    m.position.set(cx,cy,cz);
    wallFin.add(m);
  }
  BATHS.forEach(b=>{
    const off=0.02, midY=H/2, dep=b.z1-b.z0, wid=b.x1-b.x0;
    panel(greyM===undefined?whiteWall:greyMat, dep,H, b.x0+off, midY, (b.z0+b.z1)/2, Math.PI/2);   // запад: серый мрамор
    panel(whiteWall, wid,H, (b.x0+b.x1)/2, midY, b.z0+off, 0);                                     // север
    panel(whiteWall, wid,H, (b.x0+b.x1)/2, midY, b.z1-off, Math.PI);                               // юг
    // восток (стена со входом): сегменты вокруг двери + перемычка
    const ex=b.x1-off;
    if(b.dz0-b.z0>0.05) panel(whiteWall, b.dz0-b.z0, H, ex, midY, (b.z0+b.dz0)/2, -Math.PI/2);
    if(b.z1-b.dz1>0.05) panel(whiteWall, b.z1-b.dz1, H, ex, midY, (b.dz1+b.z1)/2, -Math.PI/2);
    panel(whiteWall, b.dz1-b.dz0, H-2.1, ex, 2.1+(H-2.1)/2, (b.dz0+b.dz1)/2, -Math.PI/2);
  });

  // проём на балкон (кухня 4 → лоджия 10, x 13.47–13.91, z 2.8–4.6, высота 2.1): откосы, верх и порог — светлое дерево
  const woodTex=canvasTex(g=>{
    const tones=['#e4d2ad','#dcc8a1','#e9d8b6','#d9c49c','#e1cfa9'];
    const rowH=26; // ~0.1 м доска при канвасе 1 м
    for(let r=0;r<10;r++){
      const y=r*rowH; g.fillStyle=tones[(r*3)%tones.length]; g.fillRect(0,y,256,rowH);
      g.strokeStyle='rgba(120,95,60,0.25)'; g.beginPath(); g.moveTo(0,y+0.5); g.lineTo(256,y+0.5); g.stroke();
      for(let i=0;i<3;i++){
        g.strokeStyle='rgba(120,95,60,'+(0.05+0.05*Math.random())+')';
        const gy=y+3+Math.random()*(rowH-6);
        g.beginPath(); g.moveTo(0,gy); g.bezierCurveTo(64,gy+2,192,gy-2,256,gy+1); g.stroke();
      }
    }
  });
  const woodMat=new THREE.MeshBasicMaterial({map:woodTex});
  const woodFloor=new THREE.MeshBasicMaterial({map:woodTex}); // same wood on the threshold floor; not faded by the wall slider
  const BALC=PLAN.openings.find(o=>o.tag==='balcony');
  {
    const x0=BALC.x0, x1=BALC.x1, z0=BALC.z0, z1=BALC.z1, y0=FLOOR, y1=BALC.h, d=x1-x0, w=z1-z0, in_=0.01;
    panel(woodMat, d, y1-y0, (x0+x1)/2, (y0+y1)/2, z0+in_, 0);        // откос слева (смотрит внутрь проёма)
    panel(woodMat, d, y1-y0, (x0+x1)/2, (y0+y1)/2, z1-in_, Math.PI);  // откос справа
    const top=new THREE.PlaneGeometry(d,w); scaleUV(top,d,w); top.rotateX(Math.PI/2);
    const tm=new THREE.Mesh(top,woodMat); tm.position.set((x0+x1)/2,y1-in_,(z0+z1)/2); wallFin.add(tm);
    const flr=new THREE.PlaneGeometry(d,w); scaleUV(flr,d,w); flr.rotateX(-Math.PI/2);
    const fm=new THREE.Mesh(flr,woodFloor); fm.position.set((x0+x1)/2,y0,(z0+z1)/2); finishGroup.add(fm);
  }

  // белые дверные коробки
  const DOORS=PLAN.doors; // [cx,cz,'h'|'v',ширина,(tag 'K' — дверь в съёмной стене кухни)]
  const frameMat2=new THREE.MeshBasicMaterial({color:0xffffff});
  window.kitchenFrame=new THREE.Group(); wallFin.add(window.kitchenFrame);
  window.kitchenFrame.visible=document.getElementById('kwall').checked;
  DOORS.forEach(d=>{
    const [cx,cz,o,w,tag]=d, jw=0.07, dep=0.32, hD=2.1;
    const parent = tag==='K' ? window.kitchenFrame : wallFin;
    function bx(sx,sy,sz,px,py,pz){
      const m=new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz),frameMat2);
      m.position.set(px,py,pz); parent.add(m);
    }
    if(o==='v'){
      bx(dep,hD,jw, cx,hD/2, cz-w/2-jw/2);
      bx(dep,hD,jw, cx,hD/2, cz+w/2+jw/2);
      bx(dep,jw,w+2*jw, cx,hD+jw/2, cz);
    } else {
      bx(jw,hD,dep, cx-w/2-jw/2,hD/2, cz);
      bx(jw,hD,dep, cx+w/2+jw/2,hD/2, cz);
      bx(w+2*jw,jw,dep, cx,hD+jw/2, cz);
    }
  });

  // белый плинтус 10 см (от чистового пола) и обои вдоль стен (кроме санузлов и дверных проёмов)
  const plinthMat=new THREE.MeshBasicMaterial({color:0xffffff});
  window.wallFinMats=[wpMat,whiteWall,greyMat,woodMat,frameMat2,plinthMat]; // гасятся ползунком «Стены»
  window.finishMats={lam:lamMat,white:whiteMat,whiteWall,grey:greyMat,wp:wpMat,wood:woodMat,woodFloor,plinth:plinthMat,frame:frameMat2}; // для PBR-двойников (materials.js)
  const DOORS2=DOORS;
  // room 2, M10: finish block on the north wall behind the gym wall, 0.1–2.40, x 12.15–13.75; grey until the palette stage
  const accent2Mat=new THREE.MeshBasicMaterial({color:0xd6d6d3}); wallFinMats.push(accent2Mat); finishMats.accent2=accent2Mat;
  (()=>{ const g=new THREE.PlaneGeometry(1.6,2.3); const m=new THREE.Mesh(g,accent2Mat); m.position.set(12.95,1.25,6.518+0.017); wallFin.add(m); })();
  PLAN.rooms.forEach(r=>{
    if(r.id===8||r.id===9) return;
    const poly=r.poly;
    let area=0;
    for(let i=0;i<poly.length;i++){const j=(i+1)%poly.length;area+=poly[i][0]*poly[j][1]-poly[j][0]*poly[i][1];}
    const ccw=area>0;
    for(let i=0;i<poly.length;i++){
      const a=poly[i], b=poly[(i+1)%poly.length];
      const ex=b[0]-a[0], ez=b[1]-a[1];
      const len=Math.hypot(ex,ez); if(len<0.15) continue;
      let nx=-ez/len, nz=ex/len;
      if(!ccw){nx=-nx;nz=-nz;}
      const horiz=Math.abs(ex)>Math.abs(ez);
      // диапазон вдоль оси
      const a1=horiz?a[0]:a[1], b1=horiz?b[0]:b[1];
      let lo=Math.min(a1,b1), hi=Math.max(a1,b1);
      const fixed=horiz?a[1]:a[0];
      // вычесть дверные проёмы на этой стене
      let segs=[[lo,hi]];
      const doorSpans=[]; // проёмы на этом ребре — над ними обойная перемычка
      DOORS2.forEach(d=>{
        const [cx,cz,o,w]=d;
        const near = horiz ? (o==='h'&&Math.abs(cz-fixed)<0.45) : (o==='v'&&Math.abs(cx-fixed)<0.45);
        if(!near) return;
        const c = horiz?cx:cz, d0=c-w/2-0.1, d1=c+w/2+0.1;
        if(d1>lo&&d0<hi) doorSpans.push([Math.max(d0,lo),Math.min(d1,hi)]);
        const out=[];
        segs.forEach(sg=>{
          if(d1<=sg[0]||d0>=sg[1]){out.push(sg);return;}
          if(d0>sg[0]+0.05) out.push([sg[0],d0]);
          if(d1<sg[1]-0.05) out.push([d1,sg[1]]);
        });
        segs=out;
      });
      // рёбра на съёмной Г-образной стене коридор-кухня (slabsR): их отделка прячется вместе со стеной.
      // Горизонтальное колено: z 6.287/6.464 при x<10.96; вертикальное: x 8.066/8.23 при z>5.516 (I4+09)
      const onKwallH = horiz && (Math.abs(fixed-6.287)<0.1 || Math.abs(fixed-6.464)<0.1);
      const onKwallV = !horiz && (Math.abs(fixed-8.066)<0.04 || Math.abs(fixed-8.23)<0.04);
      if(onKwallH||onKwallV){
        const cut=onKwallH?10.96:5.516; // граница съёмной части — разрезать сегменты на ней
        const out=[];
        segs.forEach(sg=>{
          if(sg[0]<cut&&sg[1]>cut){out.push([sg[0],cut],[cut,sg[1]]);}
          else out.push(sg);
        });
        segs=out;
      }
      const grpFor=mid=>((onKwallH&&mid<10.96)||(onKwallV&&mid>5.516))?window.kitchenFrame:wallFin;
      // оконные проёмы на этой стене: обои только под и над окном
      const winSpans=[];
      if(!horiz) PLAN.windows.forEach(w=>{
        if(Math.abs(w.x-fixed)>0.45) return;
        if(w.z1<=lo||w.z0>=hi) return;
        winSpans.push(w);
        const out=[];
        segs.forEach(sg=>{
          if(w.z1<=sg[0]||w.z0>=sg[1]){out.push(sg);return;}
          if(w.z0>sg[0]+0.05) out.push([sg[0],w.z0]);
          if(w.z1<sg[1]-0.05) out.push([w.z1,sg[1]]);
        });
        segs=out;
      });
      // проход на балкон в комнате 4
      if(!horiz&&Math.abs((BALC.x0+BALC.x1)/2-fixed)<0.45){
        const out=[];
        const d0=BALC.z0-0.1, d1=BALC.z1+0.1;
        if(d1>lo&&d0<hi) doorSpans.push([Math.max(d0,lo),Math.min(d1,hi)]); // перемычка над проёмом
        segs.forEach(sg=>{
          if(d1<=sg[0]||d0>=sg[1]){out.push(sg);return;}
          if(d0>sg[0]+0.05) out.push([sg[0],d0]);
          if(d1<sg[1]-0.05) out.push([d1,sg[1]]);
        });
        segs=out;
      }
      segs.forEach(sg=>{
        if(sg[1]-sg[0]<0.08) return;
        // по реальным концам ребра — работает и для слегка косых стен
        const pt=s=>{const t=(s-a1)/(b1-a1);return [a[0]+ex*t+nx*0.028,a[1]+ez*t+nz*0.028];};
        const p0=pt(sg[0]), p1=pt(sg[1]);
        const L=Math.hypot(p1[0]-p0[0],p1[1]-p0[1]);
        const m=new THREE.Mesh(new THREE.BoxGeometry(L,0.1,0.03),plinthMat);
        m.rotation.y=Math.atan2(nx,nz);
        m.position.set((p0[0]+p1[0])/2,0.05,(p0[1]+p1[1])/2); // плинтус 0–0.1 от чистового пола
        grpFor((sg[0]+sg[1])/2).add(m);
      });
      // обои: панели между проёмами (от плинтуса до потолка) и перемычки над дверями
      if(r.id!==10){
        function wpPanel(y0,y1,s0,s1){
          if(s1-s0<0.08) return;
          // класть по реальным концам ребра: бывают слегка косые стены (север комнаты 2),
          // где панель по оси утонула бы в стене. 0.015 — за сеткой стен (0.02)
          const pt=s=>{const t=(s-a1)/(b1-a1);return [a[0]+ex*t+nx*0.015,a[1]+ez*t+nz*0.015];};
          const p0=pt(s0), p1=pt(s1);
          const L=Math.hypot(p1[0]-p0[0],p1[1]-p0[1]);
          const g=new THREE.PlaneGeometry(L,y1-y0); scaleUV(g,L,y1-y0);
          g.rotateY(Math.atan2(nx,nz));
          // в постирочной 7 вместо обоев белая плитка, как в санузлах
          const m=new THREE.Mesh(g,r.id===7?whiteWall:wpMat);
          m.position.set((p0[0]+p1[0])/2,(y0+y1)/2,(p0[1]+p1[1])/2);
          grpFor((s0+s1)/2).add(m);
        }
        segs.forEach(sg=>wpPanel(0.1,H,sg[0],sg[1])); // обои от верха плинтуса
        doorSpans.forEach(sp=>wpPanel(2.1,H,sp[0],sp[1]));
        winSpans.forEach(w=>{
          if(w.y0>0.25) wpPanel(0.1,w.y0,Math.max(w.z0,lo),Math.min(w.z1,hi)); // под окном
          if(w.y1<H-0.05) wpPanel(w.y1,H,Math.max(w.z0,lo),Math.min(w.z1,hi));  // над окном
        });
      }
    }
  });
})();
scene.add(finishGroup);

// мебель — в items.js (предметы с id, локальными координатами и слоями)

// мини-карта
const mapC=document.getElementById('map');
const mapCtx=mapC.getContext('2d');
const PAD=10;
const mapSX=(mapC.width-2*PAD)/(maxX-minX), mapSZ=(mapC.height-2*PAD)/(maxZ-minZ);
const mapS=Math.min(mapSX,mapSZ);
function mx(x){return PAD+(x-minX)*mapS;}
function mz(z){return PAD+(z-minZ)*mapS;}
const mapBase=document.createElement('canvas');
mapBase.width=mapC.width; mapBase.height=mapC.height;
(function(){
  const g=mapBase.getContext('2d');
  function tracePoly(pts){g.beginPath();pts.forEach((p,i)=> i?g.lineTo(mx(p[0]),mz(p[1])):g.moveTo(mx(p[0]),mz(p[1])));g.closePath();}
  tracePoly(PLAN.outer); g.fillStyle='#b8b5ae'; g.fill();
  PLAN.rooms.forEach(r=>{tracePoly(r.poly); g.fillStyle='#f7f6f2'; g.fill();});
  tracePoly(PLAN.outer); g.strokeStyle='#8b877f'; g.lineWidth=1; g.stroke();
  // номера помещений, как на плане БТИ
  g.fillStyle='#6b6862'; g.font='600 11px system-ui,sans-serif';
  g.textAlign='center'; g.textBaseline='middle';
  PLAN.rooms.forEach(r=>g.fillText(r.id,mx(r.label[0]),mz(r.label[1])));
})();
const camDir=new THREE.Vector3();
function drawMap(){
  mapCtx.clearRect(0,0,mapC.width,mapC.height);
  mapCtx.drawImage(mapBase,0,0);
  const p=controls.fpv?controls.pos:camera.position;
  const x=Math.max(minX,Math.min(maxX,p.x)), z=Math.max(minZ,Math.min(maxZ,p.z));
  camera.getWorldDirection(camDir);
  const a=Math.atan2(camDir.x,camDir.z);
  const X=mx(x), Z=mz(z);
  mapCtx.save();
  mapCtx.translate(X,Z); mapCtx.rotate(-a);
  mapCtx.beginPath();
  mapCtx.moveTo(0,0); mapCtx.arc(0,0,16,Math.PI/2-0.5,Math.PI/2+0.5); mapCtx.closePath();
  mapCtx.fillStyle='rgba(211,47,47,0.25)'; mapCtx.fill();
  mapCtx.restore();
  mapCtx.beginPath(); mapCtx.arc(X,Z,4,0,Math.PI*2);
  mapCtx.fillStyle='#d32f2f'; mapCtx.fill();
  mapCtx.lineWidth=1.5; mapCtx.strokeStyle='#fff'; mapCtx.stroke();
}
(function loop(t){requestAnimationFrame(loop);walkStep(t||0);controls.update();placeTip();drawMap();renderer.render(scene,camera);})(0);
